"use client";

import { useState, useRef, useEffect } from "react";
import { useRouter } from "next/navigation";
import { 
  ArrowLeft, Download, Share2, CheckCircle2, 
  Sparkles, Layout, RotateCw, Image as ImageIcon,
  Check, Info, Loader2, Crown, Store, X, 
  Phone, MapPin, Globe, ShoppingBag
} from "lucide-react";
import { toPng } from "html-to-image";
import { supabase } from "@/lib/supabase";

// --- 🏰 3 ELITE A4 MASTERPIECES ---

const DesignWrapper = ({ children, id }: any) => (
  <div id={id} className="w-[794px] h-[1123px] relative overflow-hidden flex flex-col p-12 bg-white" style={{ minWidth: '794px', minHeight: '1123px' }}>
    {children}
  </div>
);

// DESIGN 1: THE SIGNATURE EMERALD
const PrestigeA4 = ({ store, products, qrCode, id }: any) => (
  <DesignWrapper id={id}>
    <div className="absolute inset-0 bg-[#043927]" />
    <div className="absolute inset-0 opacity-10 bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]" />
    <div className="absolute inset-8 border border-[#c5a358]/30" />
    
    <div className="relative z-10 flex items-center gap-4 mb-10">
      <img src={store?.logo_url} crossOrigin="anonymous" className="w-16 h-16 rounded-full border-2 border-[#c5a358] object-cover" alt="" />
      <div>
        <h2 className="text-[#c5a358] text-3xl font-black uppercase tracking-widest leading-none">{store?.name}</h2>
        <p className="text-white/40 text-[10px] uppercase font-bold tracking-[0.3em] mt-1">Established Excellence</p>
      </div>
    </div>

    <div className="relative z-10 mb-8">
      <h1 className="text-white text-5xl font-black uppercase leading-tight tracking-tighter italic">
        QUIT THE <br/> <span className="text-[#c5a358]">DM STRESS.</span>
      </h1>
      <p className="text-emerald-400 text-lg mt-4 font-bold uppercase tracking-wide border-l-4 border-emerald-500 pl-4 leading-relaxed">
        Shop our full collection 24/7. <br/>All prices are public. Order in seconds.
      </p>
    </div>

    <div className="relative z-10 grid grid-cols-3 gap-4 mb-10">
      {products.slice(0, 3).map((p: any, i: number) => (
        <div key={i} className="space-y-3">
          <div className="aspect-[3/4] rounded-2xl overflow-hidden border border-white/10 shadow-2xl">
             <img src={p.display_image} crossOrigin="anonymous" className="w-full h-full object-cover" alt="" />
          </div>
          <p className="text-[#c5a358] font-black text-lg text-center">₦{p.price?.toLocaleString()}</p>
        </div>
      ))}
    </div>

    <div className="relative z-10 mt-auto flex justify-between items-end border-t border-white/10 pt-8">
      <div className="max-w-[60%] space-y-5">
        <p className="text-white/80 text-sm italic font-medium leading-relaxed line-clamp-3">"{store?.description || "Quality you can trust, service you deserve."}"</p>
        <div className="space-y-2">
           <div className="flex items-center gap-2 text-[#c5a358] text-xs font-bold uppercase"><Phone size={14}/> {store?.phone}</div>
           <div className="flex items-center gap-2 text-[#c5a358] text-xs font-bold uppercase"><MapPin size={14}/> {store?.location}</div>
        </div>
      </div>
      <div className="flex flex-col items-end gap-3">
        <div className="p-3 bg-white rounded-3xl shadow-xl"><img src={qrCode} className="w-32 h-32" alt="QR" /></div>
        <p className="text-white font-black uppercase text-[9px] tracking-widest italic">Scan to Shop Now</p>
      </div>
    </div>
  </DesignWrapper>
);

// DESIGN 2: THE MODERN RETAIL
const ModernRetail = ({ store, products, qrCode, id }: any) => (
  <DesignWrapper id={id}>
    <div className="absolute inset-0 bg-[#F8F9FA]" />
    <div className="absolute inset-0 opacity-40 bg-[url('https://www.transparenttextures.com/patterns/linen.png')]" />
    
    <div className="relative z-10 flex justify-between items-center mb-12 border-b-2 border-[#043927] pb-6">
      <div className="flex items-center gap-4">
         <img src={store?.logo_url} crossOrigin="anonymous" className="w-14 h-14 rounded-full border border-gray-200 object-cover shadow-lg" alt="" />
         <h2 className="text-[#043927] text-4xl font-black uppercase tracking-tighter">{store?.name}</h2>
      </div>
      <div className="bg-[#043927] text-white px-4 py-1 rounded-full text-[10px] font-black uppercase">Official Storefront</div>
    </div>

    <h1 className="relative z-10 text-[#043927] text-5xl font-black uppercase leading-[0.9] tracking-tighter mb-8">
      STOP SENDING <br/> <span className="text-emerald-600 italic underline decoration-gray-200 underline-offset-8">50 PHOTOS IN DMs.</span>
    </h1>

    <div className="relative z-10 grid grid-cols-3 gap-3 mb-10 h-72">
      {products.slice(0, 3).map((p: any, i: number) => (
        <div key={i} className="flex flex-col bg-white rounded-3xl overflow-hidden shadow-xl border border-gray-100">
           <img src={p.display_image} crossOrigin="anonymous" className="h-[75%] object-cover" alt="" />
           <div className="flex-1 flex items-center justify-center bg-gray-50">
              <p className="text-[#043927] font-black text-sm">₦{p.price?.toLocaleString()}</p>
           </div>
        </div>
      ))}
    </div>

    <div className="relative z-10 p-10 bg-white rounded-[3.5rem] shadow-2xl border border-gray-100 flex-1 flex flex-col justify-between">
      <div className="grid grid-cols-2 gap-8 items-start">
        <div className="space-y-4">
           <p className="text-[#043927] font-black uppercase italic text-2xl leading-none">Catalog Live. <br/> Shop 24/7.</p>
           <p className="text-gray-400 text-xs leading-relaxed italic">"{store?.description}"</p>
           <div className="pt-4 border-t border-gray-100 flex flex-col gap-2 text-[#043927] font-bold text-[10px] uppercase">
              <span className="flex items-center gap-2"><Phone size={12}/> {store?.phone}</span>
              <span className="flex items-center gap-2"><MapPin size={12}/> {store?.location}</span>
           </div>
        </div>
        <div className="flex flex-col items-end">
           <div className="p-4 bg-gray-50 rounded-[2rem] shadow-inner mb-2 border border-gray-200"><img src={qrCode} className="w-28 h-28" alt="QR" /></div>
           <p className="text-gray-300 font-bold text-[9px] uppercase tracking-widest italic">storelink.ng/{store?.slug}</p>
        </div>
      </div>
    </div>
  </DesignWrapper>
);

// --- 🚀 MAIN STUDIO PAGE ---

export default function FlyerStudio() {
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [lastGeneratedFlyer, setLastGeneratedFlyer] = useState<string | null>(null);
  const [store, setStore] = useState<any>(null);
  const [allProducts, setAllProducts] = useState<any[]>([]);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [designIndex, setDesignIndex] = useState(0);

  useEffect(() => { fetchData(); }, []);

  const fetchData = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return router.push("/login");

      const { data: storeData } = await supabase.from("stores").select("*").eq("owner_id", user.id).single();
      const { data: productsData } = await supabase.from("products").select("*").eq("store_id", storeData?.id).order('created_at', { ascending: false });

      const resolveUrl = (path: any, bucket: string) => {
        if (!path) return "";
        // Support for image_urls (plural) as array or string
        const actualPath = Array.isArray(path) ? path[0] : path;
        if (actualPath.startsWith('http')) return actualPath;
        const { data } = supabase.storage.from(bucket).getPublicUrl(actualPath);
        return data.publicUrl;
      };

      const items = (productsData || []).map(p => ({
        ...p, display_image: resolveUrl(p.image_urls, 'products') // Plural image_urls
      }));

      setStore({ ...storeData, logo_url: resolveUrl(storeData?.logo_url, 'stores') });
      setAllProducts(items);
    } catch (e) { console.error(e); } finally { setLoading(false); }
  };

  const toggleProduct = (id: string) => {
    if (selectedIds.includes(id)) {
      setSelectedIds(selectedIds.filter(i => i !== id));
    } else if (selectedIds.length < 3) {
      setSelectedIds([...selectedIds, id]);
    }
  };

  const downloadFlyer = async () => {
    const el = document.getElementById(`export-target-${designIndex}`);
    if (!el) return;
    setGenerating(true);
    await new Promise(r => setTimeout(r, 1200));

    try {
      const dataUrl = await toPng(el, { 
        cacheBust: true, 
        pixelRatio: 4, 
        backgroundColor: '#ffffff',
        width: 794,
        height: 1123,
      });
      
      const link = document.createElement('a');
      link.download = `Empire-Design-${Date.now()}.png`;
      link.href = dataUrl;
      link.click();
      setLastGeneratedFlyer(dataUrl);
      setShowSuccess(true);
    } catch (err) { 
        console.error(err);
        alert("Render timed out. Please try again.");
    } finally { 
        setGenerating(false); 
    }
  };

  const selectedProducts = allProducts.filter(p => selectedIds.some(id => String(id) === String(p.id)));
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=600x600&color=000000&data=https://storelink.ng/${store?.slug}`;

  if (loading) return (
    <div className="h-screen flex flex-col items-center justify-center bg-[#011a12]">
      <Loader2 className="animate-spin text-emerald-500 mb-4" size={40} />
      <p className="font-black uppercase italic tracking-widest text-emerald-500">Syncing Empire Assets...</p>
    </div>
  );

  return (
    <div className="min-h-screen bg-[#0a0a0a] text-white overflow-x-hidden">
      
      {/* HEADER */}
      <nav className="p-4 md:p-6 border-b border-white/5 bg-black/80 backdrop-blur-xl sticky top-0 z-[60] flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button onClick={() => router.back()} className="p-2 hover:bg-white/5 rounded-2xl transition-all border border-white/10"><ArrowLeft size={24} /></button>
          <div>
            <h1 className="font-black uppercase italic text-lg md:text-2xl tracking-tighter text-emerald-500">Design Studio</h1>
            <p className="hidden md:block text-[10px] font-bold text-gray-500 uppercase tracking-widest">Branding: {store?.name}</p>
          </div>
        </div>
        <button onClick={() => setDesignIndex((prev) => (prev + 1) % 2)} className="bg-emerald-500 text-black px-4 py-2 md:px-6 md:py-3 rounded-2xl font-black text-[10px] uppercase shadow-[0_0_30px_rgba(16,185,129,0.3)] flex items-center gap-2">
           <RotateCw size={14} /> <span className="hidden md:inline">Switch Style</span>
        </button>
      </nav>

      <div className="max-w-[1600px] mx-auto p-4 md:p-10 grid grid-cols-1 lg:grid-cols-12 gap-10">
        
        {/* PICKER SECTION */}
        <div className="lg:col-span-4 space-y-6">
          <div className="bg-white/5 border border-white/10 p-6 md:p-8 rounded-[2.5rem] backdrop-blur-md">
            <h2 className="font-black uppercase italic text-lg mb-6 flex items-center gap-3 text-emerald-500">
              <Layout size={20}/> 1. Pick 3 Best Sellers
            </h2>
            <div className="grid grid-cols-3 gap-3">
              {allProducts.map((p) => {
                const isSelected = selectedIds.includes(p.id);
                return (
                  <button key={p.id} onClick={() => toggleProduct(p.id)} className={`relative aspect-square rounded-2xl overflow-hidden transition-all border-2 ${isSelected ? 'border-emerald-500 scale-95 shadow-xl' : 'border-white/10 opacity-30 hover:opacity-100'}`}>
                    <img src={p.display_image} className="w-full h-full object-cover" alt="" />
                    {isSelected && <div className="absolute inset-0 bg-emerald-500/40 flex items-center justify-center"><Check size={20} className="text-white" strokeWidth={4} /></div>}
                  </button>
                );
              })}
            </div>
            {selectedIds.length < 3 && <p className="mt-4 text-[10px] font-bold text-gray-500 uppercase tracking-widest italic">Please select {3 - selectedIds.length} more products...</p>}
          </div>

          <div className="bg-emerald-500 p-8 rounded-[3rem] shadow-2xl shadow-emerald-500/20 hidden lg:block">
            <Crown className="absolute -right-4 -bottom-4 text-emerald-900/10" size={120} />
            <h2 className="font-black uppercase italic text-lg mb-4 text-black flex items-center gap-2">
               <Sparkles size={20}/> 2. Render High-Res
            </h2>
            <button 
              disabled={selectedIds.length < 3 || generating} 
              onClick={downloadFlyer} 
              className="w-full py-6 bg-black text-white rounded-[2rem] font-black uppercase tracking-widest shadow-2xl flex items-center justify-center gap-4 hover:scale-[1.02] transition-all active:scale-95 disabled:opacity-50"
            >
              {generating ? <Loader2 className="animate-spin" /> : <Download />} {generating ? "Rendering..." : "Export Masterpiece"}
            </button>
          </div>
        </div>

        {/* PREVIEW BOOTH */}
        <div className="lg:col-span-8 flex justify-center">
          <div className="bg-black w-full rounded-[3rem] md:rounded-[5rem] border border-white/5 p-4 md:p-16 lg:p-24 shadow-inner flex flex-col items-center justify-center relative overflow-hidden min-h-[700px] md:min-h-[1000px]">
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-emerald-500/10 via-transparent to-transparent opacity-50" />
            
            <div className="relative z-10 w-full flex items-center justify-center">
               <div className="shadow-[0_100px_120px_-20px_rgba(0,0,0,1)] bg-white transform scale-[0.35] md:scale-[0.55] lg:scale-[0.7] origin-top transition-all duration-500 rounded-sm overflow-hidden">
                  {selectedIds.length === 3 ? (
                     <>
                       {designIndex === 0 && <PrestigeA4 store={store} products={selectedProducts} qrCode={qrUrl} />}
                       {designIndex === 1 && <ModernRetail store={store} products={selectedProducts} qrCode={qrUrl} />}
                     </>
                  ) : (
                    <div className="w-[794px] h-[1123px] bg-white flex flex-col items-center justify-center text-gray-200">
                       <ShoppingBag size={200} strokeWidth={0.5} />
                       <h2 className="text-8xl font-black uppercase italic tracking-tighter mt-10">Select 3 Items</h2>
                    </div>
                  )}
               </div>
            </div>
            <div className="h-[200px] md:h-[450px] lg:h-[650px]" />
          </div>
        </div>
      </div>

      {/* HIDDEN RENDER PORTAL (FIXES THE CROPPING ISSUE) */}
      <div className="fixed top-0 left-0 pointer-events-none opacity-0" style={{ width: '794px', height: '1123px', zIndex: -1 }}>
          <PrestigeA4 id="export-target-0" store={store} products={selectedProducts} qrCode={qrUrl} />
          <ModernRetail id="export-target-1" store={store} products={selectedProducts} qrCode={qrUrl} />
      </div>

      {/* MOBILE ACTION BAR */}
      <div className="lg:hidden fixed bottom-6 inset-x-6 z-[100]">
         <button 
           disabled={selectedIds.length < 3 || generating}
           onClick={downloadFlyer}
           className="w-full bg-emerald-500 text-black py-5 rounded-3xl font-black uppercase tracking-widest shadow-[0_20px_50px_rgba(16,185,129,0.4)] flex items-center justify-center gap-3 active:scale-95 transition-all"
         >
           {generating ? <Loader2 className="animate-spin" size={20} /> : <Download size={20} />}
           {generating ? "Exporting..." : "Download Design"}
         </button>
      </div>

      {/* SUCCESS MODAL */}
      {showSuccess && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/98 backdrop-blur-3xl animate-in fade-in duration-500">
          <div className="bg-white rounded-[4rem] p-10 md:p-14 text-center space-y-8 max-w-lg w-full text-gray-900 shadow-2xl animate-in zoom-in-95 duration-300 relative">
            <button onClick={() => {setShowSuccess(false); setGenerating(false);}} className="absolute top-10 right-10 text-gray-300 hover:text-black transition-all"><X size={32} /></button>
            <div className="w-24 h-24 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto shadow-inner"><CheckCircle2 size={50} strokeWidth={3} className="animate-bounce" /></div>
            <h2 className="text-4xl md:text-5xl font-black uppercase italic tracking-tighter text-[#043927]">Masterpiece! 🏰</h2>
            <div className="aspect-[3/4] w-64 mx-auto rounded-3xl overflow-hidden shadow-2xl border-8 border-gray-100 rotate-3">
               <img src={lastGeneratedFlyer || ''} className="w-full h-full object-cover" alt="" />
            </div>
            <div className="space-y-4 pt-4">
              <button 
                onClick={() => window.open(`https://wa.me/?text=${encodeURIComponent('Our new storefront is LIVE! 🏰✨\n\nNo more "How much" chats. Shop directly here: storelink.ng/' + store?.slug)}`, '_blank')} 
                className="w-full py-6 bg-emerald-600 text-white rounded-[2rem] font-black uppercase flex items-center justify-center gap-4 hover:scale-105 shadow-xl transition-all shadow-emerald-200"
              >
                <Share2 size={24} /> Share Link
              </button>
              <button 
                onClick={() => { setShowSuccess(false); setGenerating(false); }} 
                className="text-gray-400 uppercase font-black text-[11px] tracking-[0.3em] italic hover:text-emerald-600 transition-colors py-2 block w-full"
              >
                Done, Back to Suite
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}